from __future__ import annotations
import xml.etree.ElementTree as ET
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether, Flowable

ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'submission'/'reports';OUT.mkdir(parents=True,exist_ok=True)
INK=colors.HexColor('#183252');BLUE=colors.HexColor('#2D66C5');MUTED=colors.HexColor('#66768C');PALE=colors.HexColor('#EEF4FB');GREEN=colors.HexColor('#26795B')
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='CoverTitle',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=27,leading=32,textColor=INK,alignment=TA_CENTER,spaceAfter=16));styles.add(ParagraphStyle(name='Section',parent=styles['Heading1'],fontName='Helvetica-Bold',fontSize=18,leading=23,textColor=INK,spaceAfter=11));styles.add(ParagraphStyle(name='Sub',parent=styles['Heading2'],fontName='Helvetica-Bold',fontSize=11,leading=14,textColor=BLUE,spaceBefore=6,spaceAfter=5));styles.add(ParagraphStyle(name='Body2',parent=styles['BodyText'],fontName='Helvetica',fontSize=9.1,leading=13,textColor=colors.HexColor('#34445A'),spaceAfter=7));styles.add(ParagraphStyle(name='Small2',parent=styles['BodyText'],fontSize=7.2,leading=9,textColor=MUTED));styles.add(ParagraphStyle(name='Bullet2',parent=styles['BodyText'],fontSize=8.8,leading=12,leftIndent=14,firstLineIndent=-8,spaceAfter=4,textColor=colors.HexColor('#34445A')))

def P(text,style='Body2'):return Paragraph(text,styles[style])
def bullets(items):return [P('- '+i,'Bullet2') for i in items]
def table(rows,widths=None):
    converted=[[P(str(c),'Small2') for c in row] for row in rows]
    t=Table(converted,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),INK),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,PALE]),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#DCE4EF')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));return t
class ArchitectureDiagram(Flowable):
    def __init__(self,width=450,height=116):super().__init__();self.width=width;self.height=height
    def draw(self):
        c=self.canv
        nodes=[('Browser',20),('FastAPI + RBAC',145),('Crypto services',285),('SQLite / encrypted files',405)]
        for i,(label,x) in enumerate(nodes):
            c.setFillColor(PALE);c.setStrokeColor(colors.HexColor('#C8D7EB'));c.roundRect(x,42,105,42,8,fill=1,stroke=1);c.setFillColor(INK);c.setFont('Helvetica-Bold',7.5);c.drawCentredString(x+52,59,label)
            if i<len(nodes)-1:
                c.setStrokeColor(BLUE);c.line(x+106,63,nodes[i+1][1]-5,63);c.line(nodes[i+1][1]-5,63,nodes[i+1][1]-10,66);c.line(nodes[i+1][1]-5,63,nodes[i+1][1]-10,60)
        c.setFillColor(MUTED);c.setFont('Helvetica',7.2);c.drawCentredString(self.width/2,20,'TLS protects browser transport  -  Root CA key remains outside the running API process')

def on_page(canvas,doc):
    canvas.saveState();w,h=letter;canvas.setStrokeColor(colors.HexColor('#E6ECF4'));canvas.line(.65*inch,.55*inch,w-.65*inch,.55*inch);canvas.setFont('Helvetica',7);canvas.setFillColor(MUTED);canvas.drawString(.65*inch,.38*inch,'EduSecure  -  ICT-N-416  -  Local academic demonstration');canvas.drawRightString(w-.65*inch,.38*inch,f'Page {doc.page}');canvas.restoreState()

def read_test_counts():
    path=ROOT/'submission'/'evidence'/'junit.xml'
    if not path.exists():return {'tests':0,'failures':0,'errors':0,'skipped':0}
    root=ET.parse(path).getroot();suites=root.findall('.//testsuite') or [root]
    return {k:sum(int(s.attrib.get(k,0)) for s in suites) for k in ('tests','failures','errors','skipped')}
def page(title,*items):return [P(title,'Section'),*items]
def build_pdf(path,pages):
    story=[]
    def flatten(items):
        for item in items:
            if isinstance(item,list): yield from flatten(item)
            else: yield item
    for idx,content in enumerate(pages):
        if idx:story.append(PageBreak())
        story.extend(flatten(content))
    doc=SimpleDocTemplate(str(path),pagesize=letter,rightMargin=.68*inch,leftMargin=.68*inch,topMargin=.66*inch,bottomMargin=.72*inch,title=path.stem,author='EduSecure Academic Project')
    doc.build(story,onFirstPage=on_page,onLaterPages=on_page)

def main():
    counts=read_test_counts();actual=f"{counts['tests']} tests; failures={counts['failures']}; errors={counts['errors']}; skipped={counts['skipped']}."
    missing=P('<b>Specification source:</b> The pasted build prompt refers to a 16-page PDF, but that PDF was not supplied. This document reflects the pasted requirements only and must be reconciled with the course PDF when available.','Body2')
    task1=[
      page('1. Project overview',P('EduSecure is a local educational-platform demonstration for ICT-N-416. It protects course files, academic grades, login sessions, payment events, and digital credentials through layered cryptographic controls. The local build combines a FastAPI service, SQLite persistence, vetted Python cryptographic libraries, and a React/TypeScript web interface.'),P('The central design principle is authenticated protection at multiple boundaries: transport encryption does not replace authorization; encryption at rest does not replace integrity verification; and payment state changes occur only after a signed, fresh event matches its order.'),missing),
      page('2. Threat model and architecture',P('The browser and network are untrusted. The API process, local database, and files form the demonstration server boundary. A simulated gateway shares an independent webhook secret. A local Root CA signs the server and issuer certificates. The online issuer key is separate from the Root CA key; the Root CA private key is not loaded by the application process after bootstrap.'),ArchitectureDiagram(),table([['Boundary','Control','Failure response'],['Browser to API','TLS 1.2+; ECDSA certificate; HSTS/CSP','Untrusted chain or unsupported suite fails handshake'],['API to database/files','RBAC; AES-GCM; wrapped DEKs; SHA-256','Unauthorized access or altered ciphertext rejected'],['Gateway to payment handler','HMAC-SHA256 over timestamp + raw body','Bad signature, stale timestamp, mismatch, or replay rejected'],['Issuer to verifier','Canonical JSON; ECDSA P-256; X.509 chain','Modified document or untrusted chain marked invalid']],[1.15*inch,2.45*inch,2.45*inch])),
      page('3. Six security layers and algorithm choices',table([['Layer','Algorithms','Purpose'],['Transport','TLS 1.2+, TLS 1.3; ECDSA; AES-GCM suites','Protect browser/API transport and authenticate local server'],['Secure channel exercise','X25519; HKDF-SHA256; AES-256-GCM; ECDSA','Authenticated ephemeral key agreement, directional records, replay rejection'],['Authentication','PBKDF2-HMAC-SHA256; HMAC-SHA256; CSRF','Password verification, signed sessions, request integrity'],['Payments','HMAC-SHA256','Verify gateway origin, freshness, amount/currency, and one-time transition'],['Credentials','SHA-256; ECDSA P-256; X.509','Detect document changes and establish issuer trust'],['Data at rest','AES-256-GCM; RSA-3072-OAEP/SHA-256; SHA-256','Encrypt records with per-object keys, wrap keys, verify digests']],[1.1*inch,2.45*inch,2.5*inch]),P('PBKDF2 uses 600,000 iterations and 16-byte random salts. Each file and grade gets an independent random 256-bit AES key and 96-bit GCM nonce. The educational channel is not used in place of TLS.'),P('Task 1 weighting: threat model 1.5/5; architecture and algorithms 2/5; key plan 1.5/5.')),
      page('4. Key management and security rationale',P('The Root CA, ECDSA credential issuer, TLS server identity, RSA-3072 wrapping key, session HMAC key, and webhook HMAC key have separate responsibilities. Private signing and unwrapping keys remain outside SQLite and frontend responses. The root certificate is public and downloadable; the root signing key is generated through a separate bootstrap command.'),bullets(['Local private-key files are excluded from source control and source ZIP packaging.','DEKs exist in memory during use and are stored in the database only after RSA-OAEP wrapping.','Session and webhook secrets should be configured independently through environment variables; generated local defaults change on process start.','Production custody requires an offline Root CA ceremony and HSM/KMS storage for online issuer and wrapping keys.','Rotation, revocation, encrypted backups, and recovery drills are documented as future production operations, not claimed as implemented.']),P('Limitations include weak-password risk, no MFA, local filesystem custody, no revocation service, simulated payment events, and RSA/ECC/X25519 exposure to future quantum cryptanalysis. A migration path is hybrid ML-KEM (FIPS 203) and ML-DSA (FIPS 204); neither is implemented.'))]
    build_pdf(OUT/'task1-design-threat-model.pdf',task1)

    evidence=[
      page('Task 2  -  Core prototype evidence',P('Build verification was executed locally against the project source. Test summary: <b>'+actual+'</b>'),table([['Check','Observed result'],['Backend cryptographic/API suite',actual],['Frontend production build','TypeScript check and Vite build completed successfully'],['TLS trust exercise','Trusted local Root CA accepted; untrusted CA rejected'],['TLS 1.2','Negotiated ECDHE-ECDSA-AES256-GCM-SHA384'],['TLS 1.3','Handshake accepted where supported by runtime'],['Security headers','HSTS and Content-Security-Policy present'],['Encrypted file attack','Stored ciphertext changed; download failed before plaintext response'],['Webhook attack','Invalid/expired/mismatched events rejected; valid event enrolled once']],[2.1*inch,3.8*inch]),P('<b>Warning:</b> pytest emits one StarletteDeprecationWarning because the installed TestClient integration uses httpx; it does not affect assertions or the test outcomes.'),P('The actual TLS test opens a local HTTPS server, establishes handshakes with trust and non-trust contexts, checks the selected cipher, and reads response headers. The file attack uses the application upload/download path and verifies that plaintext is not returned after ciphertext modification.'),missing),
      page('Evidence notes and reproducibility',P('Run `python -m pytest backend/tests -q` for automated tests. Run `python scripts/verify_tls.py` while `python scripts/serve_https.py` is active to repeat the transport check. Run `python scripts/attack_demo.py` for signed-webhook and ciphertext attacks.'),P('No screenshot is embedded in this note; the results above are from executed test artifacts rather than mock interface indicators. The source tree contains the interactive user interface, backend routes, cryptographic modules, test code, TLS runner, and reproducible attack commands.'),P('The local demo is not production payment integration and does not store payment card numbers. Keep local generated credentials out of the source ZIP.'))]
    build_pdf(OUT/'task2-evidence-note.pdf',evidence)

    final=[
      page('EduSecure  -  Final project report',P('Layered Cryptographic Security for an Educational Platform','CoverTitle'),P('ICT-N-416  -  Encryption Algorithm<br/>New Cairo Technological University<br/>Fourth Year  -  Bachelor of Technology in Information Technology','Body2'),Spacer(1,18),P('Prepared as a local academic engineering demonstration. This report documents the implementation in the accompanying source tree and records actual automated verification.','Body2'),missing,P('Version 1.0  -  16 November 2026','Small2')),
      page('1. Executive summary',P('EduSecure demonstrates how several cryptographic mechanisms work together to protect a small educational workflow. The implementation includes browser/API HTTPS, a separate authenticated X25519 channel exercise, role-protected student and instructor routes, encrypted files and grades, an HMAC payment simulator, and signed digital credentials.'),P('The backend uses FastAPI, SQLAlchemy, and SQLite. The frontend uses React, TypeScript, and Vite. Python&apos;s maintained `cryptography` library supplies cryptographic primitives. Tests cover known-answer vectors, failure cases, API authorization, file-tampering attacks, payment replay, and actual local TLS handshakes.'),P('This remains a local demo: no real payment processor, MFA, HSM, revocation service, or post-quantum scheme is present. The referenced 16-page academic PDF was not supplied; therefore this report maps to the pasted master prompt and should be reconciled against that primary specification.')),
      page('2. System scope and workflows',P('Students register, browse courses, initiate simulated checkout, access enrolled materials, view their grades, and verify credentials. Instructors create courses, upload materials, view course-scoped rosters, enter grades, and issue credentials for enrolled students. Course records, payment orders, enrollments, encrypted file metadata, wrapped keys, grade envelopes, and signed credentials are stored locally.'),bullets(['Student flow: register - course selection - pending order - simulated signed webhook - enrollment.','Instructor flow: create course - upload file - publish encrypted grade - issue credential to enrolled learner.','Verifier flow: load canonical credential - recompute digest - verify ECDSA signature - confirm issuer certificate chain.','Security demonstration: inspect actual configuration, run crypto exercises, then execute rejected attack cases.']),P('Pages and APIs share one service, which keeps the educational demo understandable. Role checks and enrollment checks run on the backend even when the UI hides actions.')),
      page('3. Architecture and data flow',ArchitectureDiagram(),P('The API separates routing, SQLAlchemy entities, configuration, and cryptographic wrappers. Student/instructor browsers use same-origin API calls. The local TLS server terminates HTTPS with an ECDSA certificate. A separate X25519 component verifies its signer certificate chain and signature before deriving directional record keys. It never replaces web TLS.'),P('SQLite contains account password salts/digests, course/order/enrollment state, grade ciphertext, file metadata, wrapped DEKs, and credential envelopes. `storage/encrypted` contains file ciphertext. Verified plaintext is materialized only in a temporary directory during download and is deleted after the response completes.')),
      page('4. Layer 1  -  Transport security',P('The local certificate hierarchy includes a self-signed ECDSA P-256 Root CA, an ECDSA server certificate with localhost names, and a separate ECDSA credential issuer certificate. A separate bootstrap command creates material; the service loads its server, issuer, and RSA wrapping keys but not the Root CA private key.'),bullets(['TLS minimum: 1.2. TLS 1.3 is enabled by the runtime.','TLS 1.2 suite is constrained to ECDHE-ECDSA-AES256-GCM-SHA384.','The verification script uses the project Root CA for the trusted request and an empty system trust context for the rejection check.','Responses include HSTS and a restrictive Content-Security-Policy.']),P('This certificate is only trusted after the user explicitly installs the local Root CA. No automatic trust override is used. The test verifies a live handshake rather than displaying a simulated UI state.')),
      page('5. Layer 2  -  Secure channel exercise',P('The standalone exercise creates fresh one-time X25519 key pairs for client and server. It signs a transcript containing both public keys and a random session identifier with the issuer ECDSA key. The client validates the issuer-to-Root chain and verifies the transcript signature before accepting the exchange.'),P('Both endpoints calculate the X25519 secret and derive separate client-to-server and server-to-client AES-256-GCM keys with HKDF-SHA256. Each record uses an independent random nonce and places its monotonic sequence number in authenticated additional data. The receiver rejects out-of-order/replayed sequence values and GCM rejects modified ciphertext. The component is explicitly educational; TLS remains application transport.')),
      page('6. Layer 3  -  Authentication and authorization',P('Registration derives a 32-byte password verifier with PBKDF2-HMAC-SHA256, 600,000 iterations, and a random 16-byte salt. Unknown email attempts run a dummy derivation and return generic credential errors. Five failed password checks trigger a five-minute account lockout.'),P('An eight-hour session payload is authenticated with HMAC-SHA256. The session cookie is HttpOnly, Secure in the HTTPS runner, SameSite=Lax, and path scoped. A random CSRF value is embedded in the signed session and checked on state-changing application forms. Backend dependencies enforce student/instructor roles. Instructor self-registration requires a configured invite code; the seed command generates local instructor/student accounts with random one-time passwords.'),P('There is no MFA, password recovery, distributed rate limiting, or identity-proofing workflow.')),
      page('7. Layer 4  -  Payment security',P('Checkout creates a pending order from the course&apos;s stored price and currency. The demonstration gateway creates a canonical event and authenticates the raw request body together with its timestamp using HMAC-SHA256. The handler checks signature in constant time, a five-minute timestamp tolerance, order existence, exact amount and currency, pending state, and unique event ID.'),P('Only after those checks pass does the handler transition the order to paid and create enrollment. Duplicate or replayed events are rejected. Tests separately exercise forged signatures, stale timestamps, amount mismatches, successful enrollment, and duplicate processing. The simulator requests no card numbers/CVV and must not be represented as a real payment-provider integration.')),
      page('8. Layer 5  -  Credentials and certificates',P('Credential documents are serialized as canonical JSON with stable key ordering and compact separators. The issuer computes a SHA-256 digest and signs the document using ECDSA P-256. Verification recomputes the digest, validates the signature, checks certificate validity, verifies the issuer certificate under the Root CA, and confirms the local Root trust anchor.'),P('Tampering with student or course fields invalidates the signature. Credentials are stored with an ID, course/student relation, canonical document, digest, and signature. The student-facing verification screen displays actual results from the backend operation. There is no certificate revocation list or online status protocol; local trust does not imply institutional accreditation.')),
      page('9. Layer 6  -  Data at rest',P('Every uploaded course file and every grade record uses a fresh random 256-bit AES DEK and 96-bit nonce with AES-256-GCM. Course ID or student/course identity is authenticated as AAD. The DEK is wrapped by the separate RSA-3072 private key using RSA-OAEP with SHA-256 and MGF1-SHA256. The database stores wrapped key and SHA-256 plaintext digest, while file storage holds ciphertext.'),P('Download requires authentication plus ownership or enrollment. The service unwraps the DEK, verifies GCM authentication, recomputes and constant-time compares SHA-256, and only then creates a temporary response file. On any failure the route returns an error without sending verified plaintext. Tests verify stored bytes contain no readable sample, authorized download returns the content, unauthorized access is denied, and tampering is rejected.')),
      page('10. Threat analysis and key custody',P('Brute force is mitigated by an expensive password derivation and lockout, but lockout itself can be used for denial of service. Implementation attacks are addressed with vetted library primitives, unique random keys/nonces, authenticated AAD, constant-time MAC comparisons, strict parsing, route authorization, and adversarial tests. Social engineering remains outside cryptographic controls. Mathematical cryptanalysis risk includes future quantum attacks on RSA, ECDSA, and X25519.'),P('Keys are separated by purpose and excluded from source packages. The Root key is not loaded by the API after bootstrap, but remains in a local file. The issuer and unwrapping keys remain online. Production needs an offline Root CA process, HSM/KMS custody, encrypted backups, tested rotation/recovery, certificate revocation, operational monitoring, MFA, and a real hosted payment provider. A future migration should evaluate hybrid ML-KEM and ML-DSA without claiming current post-quantum security.')),
      page('11. Testing, attacks, and cryptanalysis discussion',P('The executed suite summary is <b>'+actual+'</b> It includes real AES-GCM round trips and tamper rejection, RSA-OAEP wrap/unwrap, SHA-256 and PBKDF2/HMAC known-answer checks, X25519/HKDF agreement, ECDSA valid/invalid signatures, signed document tampering, payment freshness/forgery/replay, role checks, grade privacy, file authorization/tampering, credentials, and local HTTPS.'),P('The automated TLS test starts the project server, trusts only the local Root for one client, confirms rejection for another, negotiates the required TLS 1.2 cipher, checks TLS 1.3, and validates HSTS/CSP. `scripts/attack_demo.py` repeats webhook/file attacks. `scripts/verify_tls.py` supports a live instructor demonstration.'),P('The test run emitted one StarletteDeprecationWarning about the httpx TestClient integration; all test assertions passed. No claim of formal cryptanalysis, FIPS validation, production security audit, or resistance to a compromised host is made.')),
      page('12. Limitations, references, and conclusion',P('Known scope limits: local SQLite and filesystem storage; local HMAC secrets; no payment-provider integration; no MFA; no revocation; no HSM/KMS; no automated backup/recovery; no protection from server administrator or host compromise; no post-quantum cryptography. TLS CA browser trust is an explicit local setup step. The absent academic PDF remains a source-specification gap.'),P('<b>References</b><br/><link href="https://www.rfc-editor.org/rfc/rfc9846.html">RFC 9846, TLS 1.3 (2026)</link>; <link href="https://www.rfc-editor.org/rfc/rfc7748.html">RFC 7748, X25519</link>; <link href="https://www.rfc-editor.org/rfc/rfc5869.html">RFC 5869, HKDF</link>; <link href="https://www.rfc-editor.org/rfc/rfc8017.html">RFC 8017, RSA-OAEP</link>; <link href="https://csrc.nist.gov/pubs/sp/800/132/final">NIST SP 800-132, password derivation</link>; <link href="https://csrc.nist.gov/pubs/fips/186-5/final">NIST FIPS 186-5, DSS</link>; <link href="https://csrc.nist.gov/pubs/fips/203/final">NIST FIPS 203, ML-KEM</link>; <link href="https://csrc.nist.gov/pubs/fips/204/final">NIST FIPS 204, ML-DSA</link>.'),P('EduSecure demonstrates that secure educational workflows require authenticated encryption, key separation, identity and role checks, signed fresh transactions, and verifiable digital signatures as cooperating controls. The implementation and test evidence are included in the source package.'))]
    build_pdf(OUT/'final-project-report.pdf',final)
    print(f'Reports written to {OUT}; test summary: {actual}')
if __name__=='__main__':main()
